    ["The line at the pharmacy is out the door. [Get what you need now|I picked up your prescription]"] = "A fila da farmácia passa da porta. [Pegue o que precisa agora|Eu busquei sua receita]",
    ["The house phone is dead. [Text me on this|This thing still works]. Are you home?"] = "O telefone de casa está mudo. [Me mande mensagem por este|Este aqui ainda funciona]. Você está em casa?",
    ["There's a curfew tonight. [Be home before dark|Don't go out after dark], please"] = "Hoje tem toque de recolher. [Esteja em casa antes de escurecer|Não saia depois de escurecer], por favor",
    ["They're putting up a fence on the highway. A fence, {first}. [What is going on|Nobody tells us anything]"] = "Estão levantando uma cerca na rodovia. Uma cerca, {first}. [O que está acontecendo|Ninguém nos diz nada]",
    ["Fill your tub and some jugs with water. [Just in case|Your dad says just in case]"] = "Encha a banheira e alguns jarros de água. [Por precaução|Seu pai diz que é por precaução]",
    ["{label}: Hey, {you}! I'm at the store, can I call you back? / Love you. Bye."] = "{label}: Oi, {you}! Estou no mercado, posso te ligar depois? / Te amo. Tchau.",
    ["{label}: Hi, sweetheart. Hot enough for you? / Are you eating okay? / Okay. Call your grandmother."] = "{label}: Oi, querida. Quente o bastante pra você? / Você está se alimentando direito? / Certo. Ligue para sua avó.",
    ["{label}: Did you see the news about Louisville? / Your aunt is worried sick. / I'm sure it's nothing."] = "{label}: Você viu o noticiário sobre Louisville? / Sua tia está preocupadíssima. / Tenho certeza de que não é nada.",
    ["{label}: They closed the roads. Did you hear? / Nobody's telling us anything. / Stay close to home, okay?"] = "{label}: Fecharam as estradas. Você ouviu? / Ninguém nos diz nada. / Fique perto de casa, está bem?",
    ["{label}: I can't talk long, the line at the pharmacy is crazy. / Do you need anything? / I'll call you tonight."] = "{label}: Não posso falar muito, a fila da farmácia está uma loucura. / Você precisa de alguma coisa? / Ligo para você hoje à noite.",
    ["I'm fine, just hot. Call your grandmother"] = "Estou bem, só com calor. Ligue para sua avó",
    ["We're okay here. [The news has everybody nervous|Your dad's glued to the TV]"] = "Estamos bem aqui. [O noticiário deixou todo mundo nervoso|Seu pai está grudado na TV]",
    ["Stay close to home this week, okay?"] = "Fique perto de casa esta semana, está bem?",
    ["Don't worry about us. [We have plenty of food|We stocked up]"] = "Não se preocupe com a gente. [Temos comida de sobra|Fizemos estoque]",
    ["Love you. Be careful out there"] = "Te amo. Tome cuidado por aí",
    ["Nine-one-one, what is the address of your emergency? / Hello? Is anyone there? / (the dispatcher hangs up)"] = "Nove um um, qual é o endereço da sua emergência? / Alô? Tem alguém aí? / (a atendente desliga)",
    ["My wife hasn't slept in four days. Every noise wakes her. Sleeping pills, if you find them. {place}"] = "Minha esposa não dorme há quatro dias. Qualquer barulho a acorda. Remédio para dormir, se você achar. {place}",
    ["Sleeping pills to {place}. I'll trade whatever I have"] = "Remédio para dormir a {place}. Troco por qualquer coisa que eu tenha",
    ["The baby sleeps. I don't. Anything to help me sleep, {place}"] = "O bebê dorme. Eu não. Qualquer coisa pra me ajudar a dormir, {place}",
    ["We've been sitting in the dark since the power went. Candles or matches to {place}?"] = "Estamos sentados no escuro desde que acabou a luz. Velas ou fósforos a {place}?",
    ["Out of matches. Can't even light the stove. {place}, please"] = "Acabaram os fósforos. Nem o fogão acendo. {place}, por favor",
    ["A lighter, a box of matches, anything. {place}. The nights are the worst part"] = "Um isqueiro, uma caixa de fósforos, qualquer coisa. {place}. As noites são a pior parte",
    ["I know it's dumb. A pack of cigarettes would keep me sane. {place}"] = "Sei que é bobagem. Um maço de cigarros me manteria são. {place}",
    ["Grandpa's out of smokes and he's mean as a snake without them. {place}. Please"] = "O vovô está sem cigarro e ficou bravo feito cobra. {place}. Por favor",
    ["Cigarettes. I'll pay in canned peaches. {place}"] = "Cigarros. Pago com pêssegos em lata. {place}",
    ["Need something to clean a wound with. Disinfectant, wipes, anything. {place}"] = "Preciso de algo pra limpar um ferimento. Desinfetante, lenços, qualquer coisa. {place}",
    ["My daughter got cut on the fence. Not by one of them, the fence. I need to clean it. {place}"] = "Minha filha se cortou na cerca. Não foi um deles, foi a cerca. Preciso limpar o corte. {place}",
    ["Disinfectant or alcohol wipes to {place}. I'm more scared of infection than anything now"] = "Desinfetante ou lenços com álcool a {place}. Agora tenho mais medo de infecção do que de qualquer coisa",
    ["We're boarding up the back windows and ran out of nails. {place}"] = "Estamos tapando as janelas dos fundos e os pregos acabaram. {place}",
    ["Duct tape or nails, whatever you have. The back door won't hold another night. {place}"] = "Fita adesiva ou pregos, o que você tiver. A porta dos fundos não aguenta mais uma noite. {place}",
    ["Need nails. A box. {place}. We have the boards, just not the nails"] = "Preciso de pregos. Uma caixa. {place}. Temos as tábuas, só faltam os pregos",
    ["My son fell off the shed roof. His arm's wrong. If you have a splint, {place}"] = "Meu filho caiu do telhado do galpão. O braço dele está errado. Se você tiver uma tala, {place}",
    ["Twisted my ankle bad running from them. A splint would help. {place}"] = "Torci feio o tornozelo correndo deles. Uma tala ajudaria. {place}",
    ["Broke my wrist. Need a splint before it sets crooked. {place}"] = "Quebrei o pulso. Preciso de uma tala antes que cole torto. {place}",
    ["My sister's at {place} with her two girls. The phone just rings. Can you look?"] = "Minha irmã está em {place} com as duas filhas. O telefone só toca. Você pode ir ver?",
    ["My grandmother lives alone at {place}. She doesn't have a phone. Please check on her"] = "Minha avó mora sozinha em {place}. Ela não tem telefone. Por favor, veja como ela está",
    ["There was a light on at {place} last night. Could be our neighbors. Could you see who it is?"] = "Tinha uma luz acesa em {place} ontem à noite. Pode ser nossos vizinhos. Você poderia ver quem é?",
    ["My husband went to {place} for supplies yesterday. He hasn't come back"] = "Meu marido foi a {place} buscar suprimentos ontem. Ainda não voltou",
    ["I didn't think anyone would come"] = "Não achei que alguém viria",
    ["You're a good person. Stay that way"] = "Você é uma boa pessoa. Continue assim",
    ["Thank you. I'll stop waiting by the phone now"] = "Obrigado. Vou parar de esperar ao lado do telefone agora",
    ["I owe you. I won't forget it"] = "Eu devo uma a você. Não vou esquecer",
    ["We buried a bag behind {place} before we left. Take it"] = "Enterramos uma sacola atrás de {place} antes de partir. Pegue",
    ["It's handled. Don't come"] = "Está resolvido. Não venha",
    ["We had to move. Don't go there"] = "Tivemos que nos mudar. Não vá lá",
    ["Count the cans before anybody eats. We're short again"] = "Contem as latas antes de alguém comer. Estamos curtos de novo",
    ["{mate} found a pharmacy nobody's hit. Keep it quiet"] = "{mate} achou uma farmácia que ninguém saqueou. Mantenham em segredo",
    ["The sheriff's car on 31W has a shotgun rack. Empty it"] = "A viatura do xerife na 31W tem um suporte de espingarda. Esvaziem",
    ["Rain tonight. Good. Nobody hears us coming"] = "Chuva esta noite. Bom. Ninguém nos ouve chegando",
    ["Somebody's been in the [barn|garage|cellar] since we left. Check the locks"] = "Alguém esteve no [celeiro|galpão|porão] desde que saímos. Verifiquem as trancas",
    ["We take the farm on [Sunday|Monday|the weekend]. The family's got a dog. Bring meat"] = "A gente toma a fazenda no [domingo|segunda|fim de semana]. A família tem um cachorro. Tragam carne",
    ["No fires at camp. Smoke carries"] = "Sem fogueira no acampamento. A fumaça se espalha",
    ["{mate2} let one get in through the fence. Again"] = "{mate2} deixou um entrar pela cerca. De novo",
    ["The boss wants a head count by morning"] = "O chefe quer uma contagem de gente até de manhã",
    ["There's a woman at the [library|post office|motel] trading eggs. Take the chickens"] = "Tem uma mulher na [biblioteca|agência dos correios|pousada] trocando ovos. Levem as galinhas",
    ["Found a pickup with half a tank. {mate}, you drive"] = "Achei uma caminhonete com meio tanque. {mate}, você dirige",
    ["Anyone sees the army, you don't run. You hide"] = "Se alguém vir o exército, não corre. Se esconde",
    ["Siphon every car on the street. Every one"] = "Sifonem todos os carros da rua. Todos",
    ["Whoever took the good knife, put it back"] = "Quem pegou a faca boa, devolva",
    ["The cops' radios still work. Bring me one"] = "Os rádios dos policiais ainda funcionam. Tragam um pra mim",
    ["Water's low. Two buckets each from the creek before dark"] = "A água está acabando. Dois baldes cada um do riacho antes de escurecer",
    ["That house paid once. It'll pay again"] = "Aquela casa pagou uma vez. Vai pagar de novo",
    ["Stay in pairs. Anybody alone is anybody's"] = "Fiquem em dupla. Quem está sozinho é de qualquer um",
    ["We're not monsters. We just eat first"] = "Não somos monstros. A gente só come primeiro",
    ["Mark the doors we've done with a red X"] = "Marquem as portas que já fizemos com um X vermelho",
    ["Pack up {owner}'s stuff"] = "Juntem as coisas de {owner}",
    ["Saw {owner}'s jacket on the road. Nobody go out there"] = "Vi a jaqueta de {owner} na estrada. Ninguém vai lá",
    ["{owner}, if you're hurt, flash a light from the water tower"] = "{owner}, se você está ferido, pisque uma luz da caixa-d'água",
    ["We're moving camp. If {owner} talked, they know where we were"] = "Vamos mudar o acampamento. Se {owner} falou, eles sabem onde estávamos",
    ["Last chance, {owner}. After tonight you're one of them to us"] = "Última chance, {owner}. Depois de hoje à noite você é um deles pra nós",
    ["Whoever's got this phone: we'll find you"] = "Quem estiver com este celular: a gente vai achar você",
    ["did u eat my beans"] = "vc comeu meu feijão",
    ["boss is in a mood. stay out of the trailer"] = "o chefe tá de mau humor. fica longe do trailer",
    ["found smokes. half for you"] = "achei cigarro. metade é sua",
    ["my feet are killing me"] = "meus pés tão me matando",
    ["whose turn on the generator"] = "de quem é a vez no gerador",
    ["cant sleep. too quiet"] = "não consigo dormir. quieto demais",
    ["i covered for u"] = "te dei cobertura",
    ["they took ur bunk"] = "pegaram seu beliche",
    ["pick up please"] = "atende por favor",
    ["i kept ur knife"] = "guardei sua faca",
    ["its not the same here"] = "não é mais a mesma coisa aqui",
    ["Newsroom"] = "Redação",
    ["Walt"] = "Walt",
    ["Newsroom. / You're inside? Inside Knox County? Hold on. Can I record this? / What can you see from where you are? ... Hello? We lost you. Call back. Ask for Dana."] = "Redação. / Você está dentro? Dentro do Condado de Knox? Espere. Posso gravar isto? / O que você consegue ver daí? ... Alô? Perdemos você. Ligue de novo. Pergunte pela Dana.",
    ["Newsroom, this is Dana. / If you're the one calling from inside: they pulled our story. Nobody here is allowed to run it. / I kept your number. I'm not giving up."] = "Redação, aqui é a Dana. / Se é você quem está ligando de dentro: tiraram nossa matéria. Ninguém aqui pode publicá-la. / Guardei seu número. Não vou desistir.",
    ["You've reached the newsroom. / Leave your name and a number where we can reach you."] = "Você ligou para a redação. / Deixe seu nome e um número onde possamos falar com você.",
    ["This is Walt. / I've been listening to you folks on the shortwave every night. You're not alone, whatever they say out here. / Save your battery for the bad nights."] = "Aqui é o Walt. / Escuto vocês no rádio de ondas curtas toda noite. Vocês não estão sozinhos, seja o que for que digam aqui fora. / Poupem a bateria para as noites ruins.",
    ["Walt here. / The shortwave's gone quiet from your side. Two nights now. / If you hear this, key the radio once. Just once. I'll know."] = "Walt falando. / O rádio de ondas curtas ficou mudo do lado de vocês. Duas noites já. / Se ouvirem isto, apertem o botão do rádio uma vez. Só uma. Eu saberei.",
    ["The pool's closed. Something about the water. In this heat, {first}"] = "A piscina fechou. Algo na água. Nesse calor, {first}",
    ["Your cousin's flight got cancelled. Louisville isn't letting planes in. [Isn't that strange|Did you hear about that]?"] = "O voo da sua prima foi cancelado. Louisville não está deixando aviões entrarem. [Não é estranho|Você ouviu sobre isso]?",
    ["Church is collecting canned goods for the hospital in Louisville. Bring some Sunday"] = "A igreja está arrecadando enlatados para o hospital de Louisville. Traga alguns no domingo",
    ["There was a fight at the Fourth of July thing. Man bit somebody. [Drunk probably|Can you believe it]"] = "Teve uma briga na festa do Quatro de Julho. Um homem mordeu alguém. [Bêbado, provavelmente|Dá pra acreditar]",
    ["Your dad's been listening to the scanner all night. Says the ambulances don't stop"] = "Seu pai ficou a noite toda ouvindo o rádio da polícia. Diz que as ambulâncias não param",
    ["Stopped at the store. They're out of bottled water. In July. [Weird|Strange week]"] = "Passei na loja. Acabou a água engarrafada. Em julho. [Estranho|Semana esquisita]",
    ["The army's at the bridge. They turned your aunt around. She's staying with us"] = "O exército está na ponte. Mandaram sua tia de volta. Ela vai ficar com a gente",
    ["School says don't bring the kids tomorrow. No reason given"] = "A escola avisou para não levar as crianças amanhã. Sem motivo",
    ["Mrs. Hale next door is sick. Real sick. Her husband won't let anybody in"] = "A Sra. Hale, vizinha, está doente. Bem doente. O marido não deixa ninguém entrar",
    ["Helicopters all night. I counted six. Are you seeing this where you are?"] = "Helicópteros a noite toda. Contei seis. Você está vendo isso aí onde está?",
    ["They're saying on the radio it's a quarantine. Just a precaution. [Stay home|Don't go anywhere]"] = "Estão dizendo no rádio que é uma quarentena. Só por precaução. [Fique em casa|Não vá a lugar nenhum]",
    ["Your dad got the generator running. Just in case, he says. He keeps saying that"] = "Seu pai colocou o gerador para funcionar. Por precaução, diz ele. Ele não para de repetir isso",
    ["{label}: Hi, it's me. Nothing's wrong. / I just wanted to hear your voice. / Okay. Call me tomorrow."] = "{label}: Oi, sou eu. Não há nada errado. / Só queria ouvir sua voz. / Certo. Me ligue amanhã.",
    ["{label}: {you}! Did you see the helicopters? / Your father says it's the National Guard. / I don't like it. Stay home tonight."] = "{label}: {you}! Você viu os helicópteros? / Seu pai diz que é a Guarda Nacional. / Não gosto disso. Fique em casa hoje à noite.",
    ["{label}: I'm in line at the bank. They're only giving out two hundred dollars. / Two hundred! / I'll call you back."] = "{label}: Estou na fila do banco. Só estão liberando duzentos dólares. / Duzentos! / Ligo de volta.",
    ["Your aunt says hi. She's worried about you"] = "Sua tia mandou um oi. Ela está preocupada com você",
    ["It's probably nothing. Probably"] = "Provavelmente não é nada. Provavelmente",
    ["Call your father, he won't say it but he worries"] = "Ligue para seu pai, ele não vai dizer, mas se preocupa",
    ["This is the [Knox|Kentucky] relief convoy. Food, medicine, beds. Pickup at {place} [tonight|at first light]. Come alone and bring what you can carry, we can't feed people who show up with nothing."] = "Aqui é o comboio de ajuda [de Knox|do Kentucky]. Comida, remédios, camas. Embarque em {place} [hoje à noite|ao amanhecer]. Venha sozinho e traga o que puder carregar, não podemos alimentar quem chega de mãos vazias.",
    ["Survivor camp taking people in. Our truck stops at {place} [tonight|tomorrow morning]. Tell no one, we don't have room for everyone."] = "Acampamento de sobreviventes recebendo gente. Nosso caminhão para em {place} [hoje à noite|amanhã de manhã]. Não conte a ninguém, não temos lugar para todos.",
    ["National Guard volunteers. Evac point at {place}, [one trip only|last run]. Bring your guns and supplies, everything gets pooled at the camp."] = "Voluntários da Guarda Nacional. Ponto de evacuação em {place}, [uma viagem só|última saída]. Tragam suas armas e suprimentos, tudo é reunido no acampamento.",
    ["[We saw your light last night.|Got your number off a board in town.] We have a doctor and a generator. Meet at {place}. Come alone the first time, you understand why."] = "[Vimos sua luz ontem à noite.|Pegamos seu número num quadro na cidade.] Temos um médico e um gerador. Encontro em {place}. Venha sozinho na primeira vez, você entende por quê.",
    ["Don't go to {place}. That convoy text is a setup. They took everything Mike had and left him there."] = "Não vá a {place}. Essa mensagem do comboio é armadilha. Levaram tudo que o Mike tinha e o deixaram lá.",
    ["If you got a text about a rescue at {place}, it's a trap. Nobody is coming. Stay away."] = "Se você recebeu uma mensagem sobre um resgate em {place}, é uma armadilha. Ninguém está vindo. Fique longe.",
    ["Whoever is texting about {place}: my brother went. He never came back. Don't."] = "Quem está mandando mensagem sobre {place}: meu irmão foi. Nunca voltou. Não vá.",
    ["Thanks for coming."] = "Obrigado por vir.",
    ["[Should've|Shouldn't have] come alone."] = "[Devia|Não devia] ter vindo sozinho.",
    ["You came. Good."] = "Você veio. Bom.",
    ["Found you."] = "Achei você.",
    ["Your phone talks too much."] = "Seu celular fala demais.",
    ["[Nice|Cute] little phone. We can hear it from here."] = "[Belo|Fofo] celularzinho. A gente ouve daqui.",
    ["Stay where you are. We're coming to you."] = "Fique onde está. Estamos indo até você.",
    ["WKNX 1350, you're on the air. [Go ahead.|Who's this?|Talk to me.]"] = "WKNX 1350, você está no ar. [Pode falar.|Quem é?|Fale comigo.]",
    ["Today's news: {news}."] = "Notícias de hoje: {news}.",
    ["We had a call from {name}: {text}"] = "Recebemos uma ligação de {name}: {text}",
    ["Got a song request or a message for the county? Leave it after the beep and we'll put it on the air."] = "Quer pedir uma música ou deixar um recado para o condado? Deixe depois do bipe e colocaremos no ar.",
    ["Welcome to Knox Mobile. Your phone works while the towers have power. Indoors costs a bar: go up a floor or step outside."] = "Bem-vindo ao Knox Mobile. Seu celular funciona enquanto as torres tiverem energia. Em ambientes fechados você perde uma barra: suba um andar ou saia.",
    ["TIP: Keep it charged. A wall outlet with power, a car, a hand crank or a power bank all work. Right-click the phone for everything it can do."] = "DICA: Mantenha-o carregado. Uma tomada com energia, um carro, uma manivela ou uma bateria externa servem. Clique com o botão direito no celular para ver tudo o que ele faz.",
    ["TIP: Texts wait for a phone that's off or out of range. Group chats, Find my crew and SOS are in your apps."] = "DICA: As mensagens esperam por um celular desligado ou fora de alcance. Chats em grupo, Encontrar minha equipe e SOS estão nos seus aplicativos.",
    ["TIP: When a tower dies, a running generator at its cell site brings it back. Your phone's manual lists the sites."] = "DICA: Quando uma torre cai, um gerador ligado na estação dela a traz de volta. O manual do seu celular lista as estações.",
    ["TIP: A dropped phone can crack and a wet one can die. A case helps. Wet? Bag of rice, or open it up with a screwdriver."] = "DICA: Um celular que cai pode rachar e um molhado pode morrer. Uma capa ajuda. Molhou? Saco de arroz, ou abra-o com uma chave de fenda.",
    ["Hello?"] = "Alô?",
    ["Static. Something like breathing."] = "Estática. Algo como respiração.",
    ["Is anyone there?"] = "Tem alguém aí?",
    ["A click. The line is dead."] = "Um clique. A linha está muda.",
}
